from ode import *
A.row(4,1,c('Series solution','y=C Σ(n=0…∞) x^n/n! = Ce^x','y=C Σ(n=0…∞) (−x)^n/n!','y=C/(1−x)'),c('Convergence','All real x','|x|<1','x=0 only'),why='Coefficient matching gives (n+1)cₙ₊₁=cₙ, hence cₙ=C/n!.')
A.row(4,2,c('Series solution','y=C Σ(n=0…∞) x^(2n)/(2^n n!) = Ce^(x²/2)','y=C Σ(n=0…∞) (−1)^n x^(2n)/(2^n n!)','y=Ce^(x²)'),c('Convergence','All real x','|x|<1','x>0 only'),why='c₁=0 and (n+1)cₙ₊₁=cₙ₋₁. Odd coefficients vanish and even coefficients are C/(2^n n!).')
A.row(4,3,c('Series solution','y=C Σ(n=0…∞) x^(3n)/(3^n n!) = Ce^(x³/3)','y=C Σ(n=0…∞) x^(3n)/(n!)','y=Ce^(x²/2)'),c('Convergence','All real x','|x|<3','x=0 only'),why='c₁=c₂=0 and (n+1)cₙ₊₁=cₙ₋₂. Only powers divisible by three remain.')
A.row(4,4,c('Series about 0','y=c₀ Σ(n=0…∞) (n+1)(x/3)^n = c₀/(1−x/3)²','y=c₀ Σ(n=0…∞) (x/3)^n','y=c₀ Σ(n=0…∞) (n+1)(−x/3)^n'),c('Convergence of nonzero series','|x|<3','All real x','|x|<1'),why='(n+2)cₙ−3(n+1)cₙ₊₁=0 gives cₙ=c₀(n+1)/3^n. The zero solution extends everywhere; nonzero solutions have a pole at x=3.')
A.row(4,5,c('Complete series definition','y=Σ cₙx^n, c₀,c₁ arbitrary; cₙ₊₂=−cₙ/(n+2) for n≥0','cₙ₊₂=cₙ/(n+2)','cₙ₊₂=−cₙ/[(n+1)(n+2)]'),c('First terms','c₀(1−x²/2+x⁴/8−x⁶/48+…)+c₁(x−x³/3+x⁵/15−x⁷/105+…)','c₀ cos x+c₁ sin x','c₀(1+x²/2+…)+c₁(x+x³/3+…)'),c('Convergence','All real x','|x|<1','|x|<2'),why='The x^n coefficient is (n+2)(n+1)cₙ₊₂+(n+1)cₙ. The recurrence and two free starting coefficients determine every coefficient.')
A.row(4,6,c('Series solution','y=c₀ Σ x^(2n)/(2n)! + c₁ Σ x^(2n+1)/(2n+1)! = c₀ cosh x+c₁ sinh x','y=c₀ cos x+c₁ sin x','y=(c₀+c₁x)e^x'),c('Convergence','All real x','|x|<1','x>0 only'),why='(n+2)(n+1)cₙ₊₂=cₙ; even and odd coefficients propagate independently. Both sums start at n=0.')
A.row(4,7,c('Series solution','y=c₀+c₁ Σ(n=1…∞) x^n/n = c₀−c₁ ln(1−x)','y=c₀+c₁ Σ(n=1…∞) (−1)^n x^n/n','y=c₀+c₁e^x'),c('Convergence when c₁≠0','−1≤x<1 (radius 1)','All real x','−1<x≤1'),why='The differential equation gives cₙ₊₂=(n+1)cₙ₊₁/(n+2), so cₙ=c₁/n for n≥1. The series converges conditionally at −1, diverges at +1; termwise differential operations are justified inside |x|<1.')
A.row(4,8,c('Complete series definition','y=Σ cₙx^n; c₀,c₁ arbitrary, c₂=0, cₙ₊₃=cₙ/[(n+3)(n+2)] for n≥0','cₙ₊₃=−cₙ/[(n+3)(n+2)]','cₙ₊₂=cₙ/[(n+2)(n+1)]'),c('First terms','c₀(1+x³/6+x⁶/180+x⁹/12960+…)+c₁(x+x⁴/12+x⁷/504+x¹⁰/45360+…)','c₀ cos x+c₁ sin x','c₀(1−x³/6+…)+c₁(x−x⁴/12+…)'),c('Convergence','All real x','|x|<1','|x|<3'),why='Match y″=xy: 2c₂=0 and (n+3)(n+2)cₙ₊₃=cₙ. The resulting two power series are entire.')
A.row(4,9,c('IVP series','y=Σ(n=0…∞) x^(2n)/(2^n n!) = e^(x²/2)','y=e^(−x²/2)','y=cosh x'),c('Convergence','All real x','|x|<1','|x|<2'),why='c₀=1,c₁=0; cₙ₊₂=cₙ/(n+2), so all odd coefficients vanish.')
A.row(4,10,c('Complete IVP series','y=Σ cₙx^n; c₀=1,c₁=c₂=c₃=0; cₙ₊₄=−cₙ/[(n+4)(n+3)] for n≥0','cₙ₊₄=cₙ/[(n+4)(n+3)]','cₙ₊₂=−cₙ/[(n+2)(n+1)]'),c('First terms','1−x⁴/12+x⁸/672−x¹²/88704+…','1+x⁴/12+x⁸/672+…','1−x²/2+x⁴/24−…'),c('Convergence','All real x','|x|<1','|x|<4'),why='From y″=−x²y, the constant and linear coefficients vanish and the recurrence steps by four.')
A.row(4,11,c('Complete IVP series','y=Σ cₙx^n; c₀=0,c₁=1,c₂=0; cₙ₊₃=−(n+1)cₙ/[(n+3)(n+2)] for n≥0','cₙ₊₃=(n+1)cₙ/[(n+3)(n+2)]','cₙ₊₂=−cₙ/(n+2)'),c('First terms','x−x⁴/6+5x⁷/252−x¹⁰/567+…','x+x⁴/6+5x⁷/252+…','x−x³/3+x⁵/15−…'),c('Convergence','All real x','|x|<1','|x|<3'),why='The x^(n+1) coefficient of x²y′+xy is (n+1)cₙ; use both initial values and propagate the recurrence.')
A.row(4,12,c('a · Bessel series','J₀(x)=Σ(n=0…∞) (−1)^n x^(2n)/[4^n(n!)²]','J₀(x)=Σ(n=0…∞) x^(2n)/[4^n(n!)²]','J₀(x)=cos x'),c('a · Convergence','All real x','|x|<1','|x|<5'),c('b · A sufficient approximation on [−5,5]','T₂₀(x)=Σ(n=0…10) (−1)^n x^(2n)/[4^n(n!)²]; uniform error <0.000004','T₂(x)=1−x²/4 is accurate to 0.000004 throughout','No Taylor polynomial approximates J₀ on [−5,5]'),n('b · J₀(5), for checking the plot',mp.besselj(0,5),tol=0.000004),limited=True,why='Coefficient matching yields n²cₙ=−cₙ₋₂, c₀=1,c₁=0. For |x|≤5, terms decrease from n≥2, so the T₂₀ tail is at most 5²²/[4¹¹(11!)²]<4×10^−6. Plot successive even polynomials; the curve itself is not automatically graded.')
assert float(5**22/(4**11*s.factorial(11)**2))<.000004
# Independent coefficient residual checks for each source equation.
N=28;cs=s.symbols('c0:'+str(N));poly=sum(cs[i]*x**i for i in range(N))
for k,expr,init in [(1,s.diff(poly,x)-poly,{cs[0]:C1}),(2,s.diff(poly,x)-x*poly,{cs[0]:C1}),(3,s.diff(poly,x)-x*x*poly,{cs[0]:C1}),(4,(x-3)*s.diff(poly,x)+2*poly,{cs[0]:C1}),(5,s.diff(poly,x,2)+x*s.diff(poly,x)+poly,{cs[0]:C1,cs[1]:C2}),(6,s.diff(poly,x,2)-poly,{cs[0]:C1,cs[1]:C2}),(7,(x-1)*s.diff(poly,x,2)+s.diff(poly,x),{cs[0]:C1,cs[1]:C2}),(8,s.diff(poly,x,2)-x*poly,{cs[0]:C1,cs[1]:C2}),(9,s.diff(poly,x,2)-x*s.diff(poly,x)-poly,{cs[0]:1,cs[1]:0}),(10,s.diff(poly,x,2)+x*x*poly,{cs[0]:1,cs[1]:0}),(11,s.diff(poly,x,2)+x*x*s.diff(poly,x)+x*poly,{cs[0]:0,cs[1]:1}),(12,x*x*s.diff(poly,x,2)+x*s.diff(poly,x)+x*x*poly,{cs[0]:1,cs[1]:0})]:
 coeff=s.Poly(s.expand(expr),x);vals=dict(init)
 for power in range(N-2):
  eq=coeff.nth(power).subs(vals);unknown=sorted(eq.free_symbols&set(cs),key=lambda z:int(str(z)[1:]))
  if unknown:vals[unknown[-1]]=s.solve(eq,unknown[-1])[0]
  else:assert s.simplify(eq)==0
 cases.append({'exercise':k,'coefficientsThrough24':{str(i):str(vals[cs[i]]) for i in range(24)}})
save('section04')
